:root {
  /* Fonts */
  --font-montserrat: 'Montserrat', sans-serif;
  --font-poppins: 'Poppins', sans-serif;

  /* Base Colors */
  --white-color: #FFFFFF;
  --white-color-opc: 255, 255, 255;

  --black-color: #000000;
  --black-color-opc: 0, 0, 0;

  /* Text */
  --title-color: #172B3A;
  --title-color-opc: 23, 43, 58;

  --title-color2: #26516F;
  --title-color2-opc: 38, 81, 111;

  --text-color: #526575;
  --text-color2: #FFFFFFB2;

  --paragraph-color: #526575;
  --paragraph-color-opc: 82, 101, 117;

  --dark-text-color: #FFFFFF99;

  /* Vibrantick Brand Colors */
  --primary-color1: #086AD8;
--primary-color1-opc: 8, 106, 216;

  --primary-color2: #26516F;
  --primary-color2-opc: 38, 81, 111;

  --primary-color3: #0B83BA;
  --primary-color3-opc: 11, 131, 186;

  --primary-color4: #E8F4F9;
  --primary-color4-opc: 232, 244, 249;

  --primary-color5: #123B56;
  --primary-color5-opc: 18, 59, 86;

  /* Borders */
  --borders-color: #D9E4EA;
  --borders-color2: #FFFFFF33;
}

