.primary-btn1 {
  padding: 20px 38px;
  background-color: var(--primary-color1);
  display: inline-block;
  line-height: 1;
  border-radius: 5px;
}
@media (max-width: 576px) {
  .primary-btn1 {
    padding: 18px 30px;
  }
}
.primary-btn1 span {
  position: relative;
  display: inline-block;
  vertical-align: top;
  line-height: 1;
  text-decoration: none;
  outline: none;
  padding: 0 1.375em 0.0625em 0;
  cursor: pointer;
  background-color: transparent;
  background-position: 100% 100%;
  background-repeat: no-repeat;
  background-size: var(--background-size, 100%) 0.0625em;
  transition: background-size 0.2s linear var(--background-delay, 0.15s);
  transform: translateZ(0);
  border: none;
  background-image: linear-gradient(0deg, var(--white-color) 0%, var(--white-color) 100%);
  color: var(--white-color);
  font-family: var(--font-montserrat);
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  white-space: nowrap;
}
@media (max-width: 576px) {
  .primary-btn1 span {
    font-size: 13px;
  }
}
.primary-btn1 span::after {
  content: "\f123";
  font-family: "bootstrap-icons";
  display: block;
  position: absolute;
  right: 0;
  left: initial;
  top: 0;
  opacity: 1;
  transition: opacity 0.3s 0.15s;
  color: var(--white-color);
}
.primary-btn1 span svg {
  position: absolute;
  display: block;
  line-height: 1.8125em;
  width: 1.375em;
  height: 1.8125em;
  right: 0;
  left: initial;
  top: 50%;
  margin: -0.92em 0 0;
  fill: none;
  stroke: var(--white-color);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1px;
  stroke-dasharray: 7.95 30;
  stroke-dashoffset: var(--stroke-dashoffset, 46);
  transition: stroke-dashoffset var(--stroke-duration, 0.15s) var(--stroke-easing, linear) var(--stroke-delay, 0s);
}
.primary-btn1:hover span {
  --background-size: 0%;
  --stroke-dashoffset: 26;
  --stroke-duration: .3s;
  --stroke-easing: cubic-bezier(0.3, 1.5, 0.5, 1);
  --stroke-delay: .195s;
}
.primary-btn1:hover span::after {
  opacity: 0;
  transition-delay: 0s;
}
.primary-btn1.white-bg {
  background-color: var(--white-color);
