/* Organic Image Shape - Creates a smooth, fluid, natural edge instead of a harsh box */
.organic-img-wrapper {
    position: relative;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
    overflow: hidden;
    box-shadow: 0 20px 50px rgba(8, 106, 216, 0.08);
    height: 550px;
    transition: border-radius 0.8s ease-in-out;
}

/* Morphs shape slightly on hover for a dynamic, living feel */
.organic-img-wrapper:hover {
    border-radius: 50% 50% 30% 70% / 60% 40% 60% 40%;
}

.organic-img-wrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

