}

.minimal-stat-item p {
    font-family: var(--font-poppins);
    font-size: 13px;
    color: var(--paragraph-color);
    margin: 0;
    line-height: 1.5;
}

.primary-btn2.white-bg:hover {
  color: var(--white-color) !important;
}

/* Optional: If you ever add an icon (svg) inside this white button, this ensures it turns white on hover too */
.primary-btn2.white-bg:hover svg {
