.modern-blog-card {
    background: var(--white-color);
    border: 1px solid var(--borders-color);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
    height: 100%;
    position: relative;
    box-shadow: 0 4px 15px rgba(var(--title-color-opc), 0.03);
}

.modern-blog-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 15px 35px rgba(var(--primary-color1-opc), 0.12);
    border-color: rgba(var(--primary-color1-opc), 0.2);
}

/* Image & Badge Constraints */
.modern-blog-card .card-img-link {
    position: relative;
    display: block;
    overflow: hidden;
    height: 200px; /* Reduced to keep cards sleek and small */
}

.modern-blog-card .card-img-link img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.6s ease;
}

.modern-blog-card:hover .card-img-link img {
    transform: scale(1.08);
}

.modern-blog-card .card-badge {
    position: absolute;
    top: 0px;
    left: 50%;
    transform: translateX(-50%);
    background-color: rgba(var(--white-color-opc), 0.75); /* Stylish transparent dark */
    backdrop-filter: blur(4px);
    padding: 6px 14px;
    border-radius: 0 0 12px 12px;
    z-index: 2;
    font-family: var(--font-montserrat);
    font-size: 11px; /* Reduced for smaller size */
    font-weight: 600;
    color: var(--primary-color1);
    text-transform: uppercase;
    text-decoration: underline;
    text-underline-offset: 4px;
    letter-spacing: 0.5px;
    text-align: center;
    white-space: nowrap; /* Forces text to stay on one line */
}

.modern-blog-card .card-badge a {
   
}

/* Card Body Formatting */
.modern-blog-card .modern-card-content {
    padding: 24px;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.modern-blog-card .card-meta {
    display: flex;
    align-items: center;
    gap: 8px;
    font-family: var(--font-poppins);
    font-size: 13px;
    color: var(--text-color);
    margin-bottom: 12px;
}

.modern-blog-card .card-meta .dot {
    width: 4px;
    height: 4px;
    background-color: var(--borders-color);
    border-radius: 50%;
}

.modern-blog-card .card-title {
    font-size: 18px; /* Slightly reduced for compact cards */
    font-weight: 700;
    line-height: 1.4;
    margin-bottom: 12px;
}

.modern-blog-card .card-title a {
    color: var(--title-color);
    transition: color 0.3s ease;
}

.modern-blog-card .card-title a:hover {
    color: var(--primary-color1);
}

.modern-blog-card .card-excerpt {
    font-size: 14px;
    color: var(--paragraph-color);
    margin-bottom: 24px;
    line-height: 1.6;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.modern-blog-card .card-read-more {
    margin-top: auto;
    font-family: var(--font-poppins);
    font-size: 14px;
    font-weight: 600;
    color: var(--primary-color1);
    display: inline-flex;
    align-items: center;
    gap: 6px;
    transition: all 0.3s ease;
}

.modern-blog-card .card-read-more:hover {
    gap: 12px;
    color: var(--primary-color3);
}
/*=========================================
  MODERN TEAM CARD STYLES
=========================================*/
.text-primary-brand {
  color: var(--primary-color1) !important;
}

/* Category Headings */
.team-category-section .section-title .subtitle {
  font-family: var(--font-montserrat);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1.5px;
  color: var(--text-color);
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 15px;
}

.team-category-section .section-title .subtitle span {
  display: inline-block;
  width: 25px;
  height: 2px;
  background-color: var(--primary-color1);
}

.team-category-section .section-title .title {
  font-family: var(--font-montserrat);
  font-size: 36px;
  font-weight: 800;
  color: var(--title-color);
  line-height: 1.25;
}

/* Card Design */
.modern-team-card {
  background-color: var(--white-color);
  border-radius: 15px;
  overflow: hidden;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.05);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.modern-team-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.1);
}

.modern-team-card .team-image {
  position: relative;
  overflow: hidden;
  background-color: #36454f; /* Requested dark background for images */
  border-bottom: 4px solid var(--primary-color1);
}

.modern-team-card .team-image img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover; /* Ensures images fit well inside the gray background */
  transition: transform 0.5s ease;
}

.modern-team-card:hover .team-image img {
  transform: scale(1.08);
}

/* Social Icon Overlay */
.modern-team-card .team-social {
  position: absolute;
  bottom: -50px;
  right: 15px;
  opacity: 0;
  transition: all 0.3s ease;
  display: flex;
  gap: 10px;
}

.modern-team-card:hover .team-social {
  bottom: 15px;
  opacity: 1;
}

.modern-team-card .team-social a {
  width: 38px;
  height: 38px;
  background-color: var(--white-color);
  color: var(--primary-color1);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 16px;
  text-decoration: none;
  box-shadow: 0 4px 10px rgba(0,0,0,0.15);
  transition: all 0.3s ease;
}

.modern-team-card .team-social a:hover {
  background-color: var(--primary-color1);
  color: var(--white-color);
}

/* Text Info Area */
.modern-team-card .team-info {
  padding: 20px 15px;
  text-align: center;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.modern-team-card .team-info .name {
  font-family: var(--font-montserrat);
  font-size: 16px;
  font-weight: 700;
  color: var(--title-color);
  margin-bottom: 5px;
  text-transform: uppercase; /* Standardized names to uppercase like old site */
}

.modern-team-card .team-info .position {
  font-family: var(--font-poppins);
  font-size: 13px;
  color: var(--text-color);
  font-weight: 500;
  margin: 0;
}
/*=========================================
  TEAM HERO SECTION STYLES (Blue Theme)
=========================================*/
.team-hero-section {
  margin-top: 100px;
  padding: 120px 0;
  /* Rich blue gradient using your brand variables */
  background: radial-gradient(ellipse 60% 80% at 50% 50%, var(--primary-color5) 0%, #0C0D12 100%);
  position: relative;
  overflow: hidden;
}

/* Optional: Faint image texture over the blue gradient */
