.faq-nav-pills .nav-item .nav-link.active {
  background-color: var(--primary-color1);
  border-color: var(--primary-color1);
  color: var(--white-color);
  box-shadow: 0 10px 20px rgba(var(--primary-color1-opc), 0.25);
  transform: translateX(5px); /* Slight nudge effect */
}

.faq-nav-pills .nav-item .nav-link.active svg {
  fill: var(--white-color);
}


/* Custom Accordion Styling */
.custom-accordion .accordion-item {
  border: 1px solid var(--borders-color);
  border-radius: 12px !important; /* Forces rounded corners on all items */
  margin-bottom: 20px;
  background-color: var(--white-color);
  overflow: hidden;
  transition: all 0.3s ease;
  box-shadow: 0 4px 10px rgba(0,0,0,0.03);
}

.custom-accordion .accordion-item:hover {
  box-shadow: 0 10px 25px rgba(0,0,0,0.06);
  border-color: rgba(var(--primary-color1-opc), 0.3);
}

.custom-accordion .accordion-header {
  margin: 0;
}

/* Accordion Button (Question) */
.custom-accordion .accordion-button {
  padding: 22px 25px;
  background-color: transparent;
  color: var(--title-color);
  font-family: var(--font-montserrat);
  font-weight: 600;
  font-size: 16px;
  box-shadow: none !important;
}

/* Active/Expanded Accordion Button */
.custom-accordion .accordion-button:not(.collapsed) {
  color: var(--primary-color1);
  background-color: var(--primary-color4); /* Very light blue background when open */
  border-bottom: 1px solid var(--borders-color);
}

/* Remove Bootstrap default focus outline */
.custom-accordion .accordion-button:focus {
  border-color: transparent;
  box-shadow: none;
}

/* Accordion Body (Answer) */
.custom-accordion .accordion-body {
  padding: 25px;
  font-family: var(--font-poppins);
  font-size: 15px;
  color: var(--text-color);
  line-height: 1.7;
}

/* Modify Bootstrap's Default Accordion Arrow Color */
.custom-accordion .accordion-button::after {
  filter: grayscale(1);
  opacity: 0.5;
  transition: transform 0.3s ease;
}

.custom-accordion .accordion-button:not(.collapsed)::after {
  filter: none; /* Can be colored using SVG background encoding if preferred, currently uses default blue tint */
  opacity: 1;
}
