/*================================================
   Infinite Client Logo Marquee
=================================================*/

.client-marquee-area {
    background-color: #080808; /* Deep black background matching the reference */
    padding: 30px 0;
    overflow: hidden; /* Hides the logos outside the screen */
    display: flex;
    width: 100%;
    position: relative;
    margin-bottom: 100px;
}

/* Optional: Adds a subtle fade effect on the left and right edges */
.client-marquee-area::before,
.client-marquee-area::after {
    content: "";
    position: absolute;
    top: 0;
    width: 150px;
    height: 100%;
    z-index: 2;
    pointer-events: none;
}

.client-marquee-area::before {
    left: 0;
    background: linear-gradient(to right, #080808 0%, transparent 100%);
}

.client-marquee-area::after {
    right: 0;
    background: linear-gradient(to left, #080808 0%, transparent 100%);
}

.marquee-track {
    display: flex;
    align-items: center;
    width: max-content;
    /* 40s determines the speed. Increase to slow down, decrease to speed up */
    animation: scroll-left 40s linear infinite; 
}

/* Pause the animation when a user hovers over it */
.marquee-track:hover {
    animation-play-state: paused;
}

.marquee-group {
    display: flex;
    align-items: center;
    justify-content: space-around;
    gap: 80px; /* Space between each logo */
    padding: 0 40px;
}

.marquee-group img {
    height: 35px; /* Keeps all logos uniformly sized */
    width: auto;
    object-fit: contain;
    /* This filter forces colored logos to appear solid white */
    filter: brightness(0) invert(1); 
    opacity: 0.7;
    transition: opacity 0.3s ease, transform 0.3s ease;
    cursor: pointer;
}

.marquee-group img:hover {
    opacity: 1; /* Brightens up when hovered */
    transform: scale(1.05); /* Slight pop effect */
}

/* The Infinite Loop Animation */
@keyframes scroll-left {
    0% {
        transform: translateX(0);
    }
    100% {
        /* Moves exactly halfway (one full group) to seamlessly reset */
        transform: translateX(-50%); 
    }
}

/* Responsive adjustments for mobile devices */
@media (max-width: 768px) {
    .marquee-group {
        gap: 50px;
        padding: 0 25px;
    }
    .marquee-group img {
        height: 25px;
    }
    .client-marquee-area::before,
    .client-marquee-area::after {
        width: 50px;
    }
}
