    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.02);
    position: relative;
    overflow: hidden;
    z-index: 1;
}

/* Hover Effects */
.benefit-modern-card:hover {
    border-color: var(--primary-color1);
    transform: translateY(-8px);
    box-shadow: 0 20px 40px rgba(8, 106, 216, 0.08);
}

/* Card Header (Icon & Watermark) */
.card-header-wrap {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 25px;
}

.benefit-modern-card .icon-box {
    width: 60px;
    height: 60px;
    border-radius: 14px;
    background: var(--primary-color4);
    color: var(--primary-color1);
