}

/* Title Styling */
.benefit-title {
    font-family: var(--font-montserrat);
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--title-color);
    line-height: 1.4;
    margin: 0;
    transition: color 0.3s ease;
}

.benefit-modern-card:hover .benefit-title {
    color: var(--primary-color1);
}

/* Responsive Adjustments */
@media (max-width: 991px) {
    .benefit-main-title {
