/* --- Services Grid --- */
.sub-services-grid-3col {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* --- Service Card --- */
.service-item-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: var(--white-color);
  border: 1px solid var(--borders-color);
  border-radius: 16px;
  padding: 28px;
  text-decoration: none;
  height: 100%;
  transition: all 0.3s ease;
}

.service-item-card:hover {
  border-color: var(--primary-color1);
  box-shadow: 0 10px 25px -5px rgba(8, 106, 216, 0.1);
  transform: translateY(-3px);
}

.service-card-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  background: var(--primary-color4);
  color: var(--primary-color1);
  border-radius: 12px;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.service-card-title {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--title-color);
  margin-bottom: 12px;
  font-family: var(--font-montserrat);
  transition: color 0.3s ease;
}

.service-item-card:hover .service-card-title {
  color: var(--primary-color1);
}

.service-card-desc {
  font-size: 0.95rem;
  color: var(--paragraph-color);
  line-height: 1.6;
  margin: 0;
  font-family: var(--font-poppins);
}

.service-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 24px;
  font-weight: 600;
  font-size: 0.9rem;
  font-family: var(--font-montserrat);
  color: var(--primary-color1);
}

.service-card-footer .arrow-icon {
  font-size: 1.2rem;
  transition: transform 0.3s ease;
}

.service-item-card:hover .arrow-icon {
  transform: translateX(5px);
}

/* --- Custom Solution Banner --- */
.custom-solution-banner {
  background: radial-gradient(ellipse at top, var(--primary-color2) 0%, #0C0D12 100%);
  border-radius: 24px;
  padding: 60px 40px;
  margin-block: 80px;
  color: var(--white-color);
  box-shadow: 0 20px 40px -10px rgba(0,0,0,0.3);
  font-family: var(--font-montserrat);
}

.badge-custom-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(11, 131, 186, 0.2); 
  color: var(--primary-color3);
  padding: 8px 16px;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.custom-solution-title {
  font-size: 2.2rem;
  font-weight: 800;
  margin-top: 16px;
  margin-bottom: 12px;
  color: var(--white-color);
}

.custom-solution-desc {
  font-size: 1.1rem;
  color: rgba(255, 255, 255, 0.7);
  font-family: var(--font-poppins);
}

.custom-benefits-pills-centered {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 20px;
  margin: 32px 0;
}

.benefit-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--borders-color);
  font-family: var(--font-poppins);
}

.benefit-pill i {
  color: var(--primary-color3);
  font-size: 1.2rem;
}

.btn-custom-solution-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--primary-color1);
  color: var(--white-color);
  padding: 14px 32px;
  border: none;
  border-radius: 30px;
  font-size: 1rem;
  font-weight: 700;
  font-family: var(--font-montserrat);
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 8px 20px -6px rgba(8, 106, 216, 0.6);
}

.btn-custom-solution-cta:hover {
  background: var(--primary-color3);
  transform: translateY(-2px);
  box-shadow: 0 12px 24px -6px rgba(8, 106, 216, 0.8);
}

/* --- Responsive Layout --- */
@media (max-width: 992px) {
  .sub-services-grid-3col {
    grid-template-columns: repeat(2, 1fr);
